<math xmlns="http://www.w3.org/1998/Math/MathML" dir="rtl"><mrow><mrow><mtable columnalign="left" rowspacing="0.55em"><mtr><mtd><mrow><mo>|</mo><mi mathvariant="normal">أ</mi><mo>|</mo><mo>=</mo><mn dir="ltr">١٢</mn><mo>−</mo><mn dir="ltr">١٠</mn><mo>=</mo><mn dir="ltr">٢</mn></mrow></mtd></mtr><mtr><mtd><mrow><mo>⇒</mo><mo>|</mo><mn dir="ltr">٣</mn><mi mathvariant="normal">أ</mi><mo>|</mo></mrow></mtd></mtr></mtable><mo>=</mo><msup><mn dir="ltr">٣</mn><mn dir="ltr">٢</mn></msup><mo stretchy="true">(</mo><mn dir="ltr">٢</mn><mo stretchy="true">)</mo><mo>=</mo><mn dir="ltr">١٨</mn></mrow></mrow></math>
